import React, { InputHTMLAttributes } from 'react';
import dayjs from 'dayjs';
import Calendar from 'react-calendar';
import { Field } from 'react-final-form';
import classNames from 'classnames';

import './index.less';
import { KeyCodes } from '../../../types';

export interface CalendarPickerFieldProps extends InputHTMLAttributes<HTMLInputElement> {
  sideBar?: React.ReactNode;
  disableWeekend?: boolean;
  className?: string;
  name: string;
  changeListener?: (date?: Date | Date[]) => void;
}

function getOffsetByKey(keyCode: number): number {
  switch (keyCode) {
    case KeyCodes.RIGHT:
      return 1;
    case KeyCodes.LEFT:
      return -1;
    case KeyCodes.DOWN:
      return 7;
    case KeyCodes.UP:
      return -7;
    default:
      return 0;
  }
}

function navigatePrevOrNextMonth(index: number, max: number) {
  if (index < 0) {
    const back: any = document.querySelector('.react-calendar__navigation__prev-button');
    back.click();
  } else if (index >= max) {
    const next: any = document.querySelector('.react-calendar__navigation__next-button');
    next.click();
  }
}

function CalendarPickerField({
  sideBar,
  disableWeekend,
  name,
  className,
  changeListener,
}: CalendarPickerFieldProps) {
  const sideBarExists = sideBar !== undefined;

  const handleCalendarArrowPress = (e, input) => {
    const { keyCode } = e;
    if ([KeyCodes.UP, KeyCodes.DOWN, KeyCodes.RIGHT, KeyCodes.LEFT].includes(keyCode)) {
      try {
        const buttons: any = Array.from(
          document.querySelectorAll('.react-calendar__month-view button'),
        );

        const activeIndex = buttons.findIndex((button) =>
          button.classList.contains('react-calendar__tile--active'),
        );

        const offset = getOffsetByKey(keyCode);
        const newDate = dayjs(input.value).add(offset, 'd');
        const newIndex = activeIndex + offset;

        if (newDate.isAfter(dayjs().add(-1, 'd'))) {
          if (disableWeekend && [0, 6].includes(newDate.day())) {
            return;
          }

          input.onChange(newDate.toDate());
          navigatePrevOrNextMonth(newIndex, buttons.length);

          setTimeout(() => {
            const dayButtons: any = Array.from(
              document.querySelectorAll('.react-calendar__month-view button'),
            );

            const selectedDay = dayButtons.find((button) =>
              button.classList.contains('react-calendar__tile--active'),
            );

            selectedDay?.focus();
          });
        }
        // eslint-disable-next-line no-empty
      } catch (error) {}
    }
  };

  return (
    <div
      className={classNames('vim-calendar-container', className, {
        'has-side-bar': sideBarExists,
      })}
    >
      <Field
        name={name}
        render={({ input }) => (
          <div
            tabIndex={0}
            onKeyDown={(e) => handleCalendarArrowPress(e, input)}
            role="button"
            aria-label="Datepicker"
          >
            <Calendar
              prev2Label={null}
              next2Label={null}
              calendarType="Hebrew"
              minDate={new Date()}
              tileDisabled={({ date }) =>
                disableWeekend ? [0, 6].includes(dayjs(date).day()) : false
              }
              showNeighboringMonth
              minDetail="month"
              maxDetail="month"
              tileClassName={({ date }) =>
                classNames({
                  'react-calendar__override_color':
                    !disableWeekend &&
                    [0, 6, 5].includes(dayjs(date).day()) &&
                    dayjs(date).isAfter(dayjs().add(-1, 'd')),
                })
              }
              tileContent={({ date }) => <div className="innerDate">{dayjs(date).format('D')}</div>}
              {...input}
              onChange={(date) => {
                changeListener?.(date);
                input.onChange(date);
              }}
              value={input.value ? dayjs(input.value).toDate() : undefined}
            />
          </div>
        )}
      />

      {sideBarExists && (
        <div className="vim-calendar-container__side-bar">
          <div className="vim-calendar-container__side-bar__content">{sideBar}</div>
        </div>
      )}
    </div>
  );
}

export default CalendarPickerField;
